"""C342: online mean-variance allocation with adaptive risk aversion.

Paper: Duy Khanh Lam (2024), https://arxiv.org/abs/2406.13486
Full drafts: https://arxiv.org/pdf/2406.13486v1 and https://arxiv.org/pdf/2406.13486

Design references, with independently written implementation:
PyPortfolioOpt quadratic utility (MIT):
https://github.com/PyPortfolio/PyPortfolioOpt/blob/main/pypfopt/efficient_frontier/efficient_frontier.py
https://pypi.org/project/pyportfolioopt/
https://github.com/PyPortfolio/PyPortfolioOpt/blob/main/LICENSE
QuantConnect LEAN portfolio construction (Apache-2.0):
https://github.com/QuantConnect/Lean/blob/master/Algorithm.Framework/Portfolio/MeanVarianceOptimizationPortfolioConstructionModel.py
https://www.quantconnect.com/docs/v2/writing-algorithms/algorithm-framework/portfolio-construction/supported-models
https://github.com/QuantConnect/Lean/blob/master/LICENSE
QuantConnect Research portfolio optimization tutorial (Apache-2.0):
https://github.com/QuantConnect/Research/blob/master/Analysis/03%20Mean-Variance%20Portfolio%20Optimization%20.ipynb
https://github.com/QuantConnect/Research/blob/master/LICENSE
"""

import gzip
import hashlib
import json
import signal
from io import BytesIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from scipy.optimize import minimize


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252


def load_config():
    with (ROOT / "config.yaml").open(encoding="utf-8") as stream:
        config = yaml.safe_load(stream)
    if not (
        pd.Timestamp(config["history_start"]) < pd.Timestamp(config["evaluation_start"])
        <= pd.Timestamp(config["is_end"]) < pd.Timestamp(config["end"])
    ):
        raise ValueError("Expected history start < evaluation start <= IS end < sample end")
    tickers = [*config["universe"], config["risk_free_ticker"]]
    if len(config["universe"]) < 2 or len(set(tickers)) != len(tickers):
        raise ValueError("The universe and the risk-free proxy must have distinct tickers")
    lag = config["signal_lag_sessions"]
    if type(lag) is not int or lag < 1 or config["rebalance"] != "weekly_first_session":
        raise ValueError("Expected weekly first-session signals and a positive integer fill lag")
    alphas = config["risk_aversions"]
    if alphas != sorted(set(alphas)) or not all(np.isfinite(a) and a > 0 for a in alphas):
        raise ValueError("Risk aversions must be positive, unique, and increasing")
    for alpha in (config["initial_risk_aversion"], config["robustness"]["fixed_risk_aversion"]):
        if alpha not in alphas:
            raise ValueError("Expected initial and fixed risk aversion to be members of the grid")
    for length in (config["min_observations"], config["score_lookback_sessions"],
                   *config["robustness"]["score_lookbacks_sessions"]):
        if type(length) is not int or length < 2:
            raise ValueError("Expected a window of at least two observations")
    return config


def check_quotes(quotes, start, end):
    if (quotes.empty or not quotes.index.is_unique or not quotes.index.is_monotonic_increasing
            or quotes.index[0] < start or quotes.index[-1] > end
            or quotes.index[0] - start > pd.Timedelta(days=7)
            or end - quotes.index[-1] > pd.Timedelta(days=7)):
        raise ValueError("Yahoo price history does not cover the configured date range")
    prices = quotes.filter(regex="_(open|close)$").to_numpy()
    distributions = quotes.filter(regex="_distribution$").to_numpy()
    if not np.isfinite(quotes.to_numpy()).all() or (prices <= 0).any() or (distributions < 0).any():
        raise ValueError("Missing daily bars or invalid prices/distributions in the ETF panel")


def load_quotes(config):
    tickers = [*config["universe"], config["risk_free_ticker"]]
    start, end = pd.Timestamp(config["history_start"]), pd.Timestamp(config["end"])
    snapshot_key = json.dumps([tickers, str(start.date()), str(end.date())]).encode()
    snapshot_name = f"yahoo_daily_actions_{hashlib.sha256(snapshot_key).hexdigest()[:16]}.csv.gz"
    snapshot = config["data"]["snapshots"][snapshot_name]
    snapshot_bytes = gzip.decompress(snapshot["gzip"])
    snapshot_sha256 = hashlib.sha256(snapshot_bytes).hexdigest()
    if snapshot_sha256 != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for snapshot {snapshot_name}")

    raw = gzip.decompress(snapshot_bytes)
    with BytesIO(raw) as file:
        fetched_at = json.loads(file.readline().decode("utf-8"))["fetched_at"]
        body_offset = file.tell()
        quotes = pd.read_csv(file, index_col="date", parse_dates=["date"])
    check_quotes(quotes, start, end)

    input_sha256 = hashlib.sha256(raw[body_offset:]).hexdigest()
    print("Data source: Yahoo Finance (query2.finance.yahoo.com) daily prices and distributions "
          "originally obtained via yfinance with auto_adjust=False and actions=True, embedded in "
          f"config under data.snapshots (decompressed sha256 {snapshot_sha256}); "
          "the script does not call yfinance, FRED or any host and reads no data_cache")
    print(f"Input SHA-256: {input_sha256}")
    print(f"DATA_SHA256: {snapshot_sha256}")
    print("MARKET_DATA_SNAPSHOT: " + json.dumps({
        "path": "config.yaml", "key": "data.snapshots", "sha256": snapshot_sha256,
    }))
    return quotes, fetched_at


def total_return_quotes(quotes, tickers):
    opening = quotes[[f"{t}_open" for t in tickers]].to_numpy()
    closing = quotes[[f"{t}_close" for t in tickers]].to_numpy()
    distribution = quotes[[f"{t}_distribution" for t in tickers]].to_numpy()
    # Yahoo's OHLC already share a split-adjusted basis. Advance the total-return
    # factor using only the previous close and the cash distribution on ex-date.
    previous_close = closing[:-1]
    ex_date_reference = previous_close - distribution[1:]
    if (ex_date_reference <= 0).any():
        raise ValueError("Cash distribution is too large for total-return adjustment")
    factors = np.ones_like(closing)
    factors[1:] = np.cumprod(previous_close / ex_date_reference, axis=0)
    return opening * factors, closing * factors


def frontier_targets(dates, closing, config):
    """Compute a row of targets per risk coefficient at each first-session close."""
    alphas = config["risk_aversions"]
    n_assets = closing.shape[1]
    equal = np.full(n_assets, 1.0 / n_assets)
    weights = np.tile(equal, (len(alphas), 1))
    mean = np.zeros(n_assets)
    scatter = np.zeros((n_assets, n_assets))
    budget = {"type": "eq", "fun": lambda w: w.sum() - 1, "jac": lambda w: np.ones_like(w)}
    bounds = [(0, 1)] * n_assets
    weeks = dates.to_period("W-FRI")
    targets = {}

    for day, week in enumerate(weeks):
        if day:
            daily_return = closing[day] / closing[day - 1] - 1
            residual = daily_return - mean
            mean += residual / day
            scatter += np.outer(residual, daily_return - mean)
        if day and week == weeks[day - 1]:
            continue
        if day >= config["min_observations"]:
            annual_mean = mean * SESSIONS_PER_YEAR
            annual_covariance = (scatter + scatter.T) * (SESSIONS_PER_YEAR / (2 * day))
            for number, alpha in enumerate(alphas):
                penalty = alpha * annual_covariance
                solution = minimize(
                    lambda w: w @ penalty @ w - annual_mean @ w,
                    weights[number],
                    jac=lambda w: 2 * (penalty @ w) - annual_mean,
                    bounds=bounds, constraints=budget, method="SLSQP",
                    options={"ftol": 1e-11, "maxiter": 100},
                )
                if not solution.success or abs(solution.x.sum() - 1) > 1e-8:
                    raise RuntimeError(f"Frontier solve failed on {dates[day].date()}, alpha={alpha}: "
                                       f"{solution.message}")
                cleaned = np.where(solution.x > 1e-10, solution.x, 0.0)
                weights[number] = cleaned / cleaned.sum()
        targets[day] = weights.copy()
    return targets


def fill_at_open(positions, cash, opening, target, friction):
    current = positions * opening
    before = cash + current.sum()
    change = target * before - current
    threshold = before * 1e-10
    sales = np.where(change < -threshold, -change, 0.0)
    purchases = np.where(change > threshold, change, 0.0)
    buying_cash = cash + sales.sum() * (1 - friction)
    required = purchases.sum() * (1 + friction)
    if required > buying_cash:
        purchases *= buying_cash / required
    cash = buying_cash - purchases.sum() * (1 + friction)
    if cash < -before * 1e-12:
        raise RuntimeError("An opening fill exceeded available cash")
    positions = (current - sales + purchases) / opening
    turnover = (sales.sum() + purchases.sum()) / before
    trades = np.count_nonzero(sales) + np.count_nonzero(purchases)
    return positions, max(0.0, cash), turnover, trades


def simulate(opening, closing, close_targets, lag, friction):
    results = np.zeros((len(closing), 3))
    cash, previous_value = 1.0, 1.0
    positions = np.zeros(closing.shape[1])
    for day, open_quotes in enumerate(opening):
        target = close_targets.get(day - lag)
        if target is not None:
            positions, cash, traded, trades = fill_at_open(positions, cash, open_quotes, target, friction)
            results[day, 1:] = traded, trades
        close_value = cash + positions @ closing[day]
        results[day, 0] = close_value / previous_value - 1
        previous_value = close_value
    return results


def candidate_weights(frontier, number):
    return {day: weights[number] for day, weights in frontier.items()}


def shadow_returns(opening, closing, frontier, lag, friction, n_alphas):
    return np.column_stack([
        simulate(opening, closing, candidate_weights(frontier, number), lag, friction)[:, 0]
        for number in range(n_alphas)
    ])


def adaptive_targets(frontier, shadows, window, initial, lag):
    first_fill = next(iter(frontier)) + lag
    targets = {}
    previous = frontier[next(iter(frontier))][initial]
    for day, weights in frontier.items():
        start = day - window + 1
        chosen = initial
        if start >= first_fill:
            past = shadows[start:day + 1]
            volatility = past.std(axis=0, ddof=1)
            scores = np.divide(past.mean(axis=0), volatility, out=np.full(len(weights), -np.inf),
                               where=volatility > 0)
            tied = np.flatnonzero(np.isclose(scores, scores.max(), atol=1e-12, rtol=0))
            distance = ((weights[tied] - previous) ** 2).sum(axis=1)
            chosen = tied[distance.argmin()]
        previous = targets[day] = weights[chosen]
    return targets


def metrics(daily_results, risk_free):
    returns, turnover, trades = daily_results.T
    growth = np.r_[1.0, np.cumprod(1 + returns)]
    volatility = returns.std(ddof=1)
    excess = returns - risk_free
    excess_volatility = excess.std(ddof=1)
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / len(returns)) - 1),
        "ann_vol": float(volatility * np.sqrt(SESSIONS_PER_YEAR)),
        "sharpe": float(returns.mean() / volatility * np.sqrt(SESSIONS_PER_YEAR)) if volatility else None,
        "sharpe_excess": float(excess.mean() / excess_volatility * np.sqrt(SESSIONS_PER_YEAR))
        if excess_volatility else None,
        "max_drawdown": float((growth / np.maximum.accumulate(growth) - 1).min()),
        "total_return": float(growth[-1] - 1),
        "turnover": float(turnover.sum()),
        "n_trades": int(trades.sum()),
    }


def friction_rate(cost_bps, slippage_bps):
    if not (0 <= cost_bps and 0 <= slippage_bps and cost_bps + slippage_bps < 10_000):
        raise ValueError("Expected nonnegative costs and slippage totaling less than 10,000 bps")
    return (cost_bps + slippage_bps) / 10_000


def run():
    config = load_config()
    quotes, fetched_at = load_quotes(config)
    dates = quotes.index
    opening, closing = total_return_quotes(quotes, config["universe"])
    _, bil = total_return_quotes(quotes, [config["risk_free_ticker"]])
    risk_free = np.r_[0.0, bil[1:, 0] / bil[:-1, 0] - 1]
    start = dates.searchsorted(config["evaluation_start"])
    split = dates.searchsorted(config["is_end"], side="right")
    if min(split - start, len(dates) - split) < 2:
        raise ValueError("IS and OOS must each contain at least two reporting sessions")

    alphas = config["risk_aversions"]
    initial = alphas.index(config["initial_risk_aversion"])
    window = config["score_lookback_sessions"]
    lag = config["signal_lag_sessions"]
    friction = friction_rate(config["cost_bps"], config["slippage_bps"])
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print("PRICE_ADJUSTMENT: yfinance split-adjusted open/close, forward total-return adjustment "
          "using previous close and ex-date distributions")

    # Work with a physical IS prefix for all robustness calculations.
    is_open, is_close = total_return_quotes(quotes.iloc[:split], config["universe"])
    is_frontier = frontier_targets(dates[:split], is_close, config)
    is_shadows = shadow_returns(is_open, is_close, is_frontier, lag, friction, len(alphas))
    is_default = simulate(is_open, is_close, adaptive_targets(is_frontier, is_shadows, window, initial, lag),
                          lag, friction)
    robustness = config["robustness"]
    trial_count = 1
    print("ROBUSTNESS (IS ONLY)")
    print("  default:", json.dumps(metrics(is_default[start:], risk_free[start:split]), allow_nan=False))
    for nearby in robustness["score_lookbacks_sessions"]:
        targets = adaptive_targets(is_frontier, is_shadows, nearby, initial, lag)
        results = simulate(is_open, is_close, targets, lag, friction)
        trial_count += 1
        print(f"  score_lookback_sessions={nearby}:",
              json.dumps(metrics(results[start:], risk_free[start:split]), allow_nan=False))
    fixed = robustness["fixed_risk_aversion"]
    results = simulate(is_open, is_close, candidate_weights(is_frontier, alphas.index(fixed)), lag, friction)
    trial_count += 1
    print(f"  fixed_risk_aversion={fixed}:",
          json.dumps(metrics(results[start:], risk_free[start:split]), allow_nan=False))
    high_cost, high_slip = robustness["high_cost_bps"], robustness["high_slippage_bps"]
    stressed_friction = friction_rate(high_cost, high_slip)
    stressed_shadows = shadow_returns(is_open, is_close, is_frontier, lag, stressed_friction, len(alphas))
    stressed = simulate(is_open, is_close, adaptive_targets(is_frontier, stressed_shadows, window, initial, lag),
                        lag, stressed_friction)
    trial_count += 1
    print(f"  cost_bps={high_cost}, slippage_bps={high_slip}:",
          json.dumps(metrics(stressed[start:], risk_free[start:split]), allow_nan=False))

    frontier = frontier_targets(dates, closing, config)
    shadows = shadow_returns(opening, closing, frontier, lag, friction, len(alphas))
    daily_results = simulate(opening, closing, adaptive_targets(frontier, shadows, window, initial, lag),
                             lag, friction)
    np.testing.assert_allclose(daily_results[:split], is_default, rtol=0, atol=1e-12)
    print("LOOKAHEAD_CHECK: close-only signals, delayed open sizing, ex-date adjustments, "
          "IS prefix reproduced with the OOS rows absent")

    equal = np.full(len(config["universe"]), 1 / len(config["universe"]))
    benchmark = simulate(opening, closing, dict.fromkeys(frontier, equal), lag, friction)
    ranges = {"is": slice(start, split), "oos": slice(split, len(dates)), "full": slice(start, len(dates))}
    report = {"strategy": config["strategy"],
              "data_range": [dates[start].date().isoformat(), dates[-1].date().isoformat()]}
    benchmark_report = {"name": "Weekly equal-weight ETF universe"}
    for period, rows in ranges.items():
        report[period] = metrics(daily_results[rows], risk_free[rows])
        benchmark_report[period] = metrics(benchmark[rows], risk_free[rows])
        print(f"{period.upper()} {dates[rows.start].date()} – {dates[rows.stop - 1].date()}:",
              json.dumps(report[period], allow_nan=False))
        print(f"BENCHMARK {period.upper()}:", json.dumps(benchmark_report[period], allow_nan=False))
    report["benchmark"] = benchmark_report
    if report["full"]["n_trades"] == 0 or report["oos"]["n_trades"] == 0:
        raise RuntimeError("Expected actual simulated fills in the full and OOS periods")
    print(f"PARAM_COMBOS_TRIED: {trial_count}")
    print("RESULTS_JSON: " + json.dumps(report, ensure_ascii=False, allow_nan=False))


if __name__ == "__main__":
    signal.alarm(14 * 60)
    run()
